import {readFile, writeFile} from 'node:fs/promises'
import path from 'node:path'

const [, , sourcePath, outputPath = 'resources/js/icons/iconify-bundle.js'] = process.argv

if (!sourcePath) {
    throw new Error('Usage: node scripts/generate-icon-bundle.mjs <icon-list.txt> [output.js]')
}

const source = await readFile(path.resolve(sourcePath), 'utf8')
const corrections = {
    'solar:map-arrow-right-linearr': 'solar:map-arrow-right-linear',
    'solar:map-arrow-up-linea': 'solar:map-arrow-up-linear',
}
const requested = [...new Set(
    source
        .split(/\r?\n/)
        .map(line => line.trim())
        .map(line => corrections[line] ?? line)
        .filter(line => /^[a-z0-9-]+:[a-z0-9-]+$/.test(line)),
)].sort()

const concurrency = 16
const records = new Map()
const missing = []
let cursor = 0

const fetchIcon = async key => {
    const [prefix, name] = key.split(':')
    const response = await fetch(`https://api.iconify.design/${prefix}/${name}.svg`)

    if (!response.ok) {
        missing.push(key)
        return
    }

    const svg = await response.text()
    const viewBox = svg.match(/viewBox="0 0 ([\d.]+) ([\d.]+)"/)
    const body = svg.match(/<svg[^>]*>([\s\S]*)<\/svg>/)?.[1]

    if (!viewBox || body == null) {
        missing.push(key)
        return
    }

    records.set(key, {
        body,
        width: Number(viewBox[1]),
        height: Number(viewBox[2]),
    })
}

const worker = async () => {
    while (cursor < requested.length) {
        const key = requested[cursor++]
        await fetchIcon(key)
    }
}

await Promise.all(Array.from({length: concurrency}, worker))

const entries = [...records]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, icon]) => `    ${JSON.stringify(key)}: ${JSON.stringify(icon)},`)
    .join('\n')

const output = `// Generated by scripts/generate-icon-bundle.mjs. Do not edit manually.\n` +
    `// Iconify icons are bundled locally; no runtime network request is made.\n` +
    `export default {\n${entries}\n}\n`

await writeFile(path.resolve(outputPath), output, 'utf8')

console.log(`Requested: ${requested.length}`)
console.log(`Bundled: ${records.size}`)
console.log(`Missing: ${missing.length}`)

if (missing.length) {
    console.error(missing.sort().join('\n'))
    process.exitCode = 2
}
